/**
 * Supported in-app notification event type emitted by Day 1 API actions only.
 */
export type InAppNotificationEventType = "bill.submitted" | "bill.participant_accepted" | "bill.participant_rejected" | "bill.confirmed" | "settlement.request_created" | "settlement.payment_marked_paid" | "settlement.payment_partially_paid" | "settlement.payment_confirmed" | "settlement.request_disputed" | "settlement.payment_disputed" | "settlement.request_cancelled" | "settlement.payment_cancelled" | "settlement.proof_attached" | "recurring_bill.draft_generated";

/**
 * Current lifecycle state for an in-app notification.
 */
export type InAppNotificationStatus = "unread" | "read" | "archived";

/**
 * Bounded in-app notification priority for inbox presentation.
 */
export type InAppNotificationPriority = "normal" | "attention" | "urgent";

/**
 * Stable subject family linked by optional IDs on a notification.
 */
export type InAppNotificationSubjectType = "expense_bill" | "settlement_request" | "settlement_payment" | "recurring_bill_occurrence";

/**
 * Bounded archive visibility filter or lifecycle state for expense bills.
 */
export type ExpenseBillArchiveState = "active" | "archived" | "all";

/**
 * Expense bill root status.
 */
export type ExpenseBillStatus = "draft" | "pending_confirmation" | "confirmed" | "rejected" | "cancelled" | "finalized" | "archived";

/**
 * Manual bill reconciliation status. This is a recordkeeping label only and does not change financial truth, bill totals, split shares, settlement state, payer state, files, or OCR state.
 */
export type ExpenseBillReconciliationStatus = "unreconciled" | "reconciled" | "ignored";

/**
 * Expense bill participant status.
 */
export type ExpenseBillParticipantStatus = "pending_acceptance" | "accepted" | "rejected" | "partially_settled" | "settled" | "waived" | "claimed_paid" | "confirmed_paid";

/**
 * Bill revision proposal lifecycle status.
 */
export type ExpenseBillRevisionStatus = "draft_revision" | "submitted_for_review" | "withdrawn_by_proposer" | "superseded_by_resubmission" | "rejected" | "accepted_applied" | "cancelled_by_authorized_editor";

/**
 * Bill revision approval status.
 */
export type ExpenseBillRevisionApprovalStatus = "pending_review" | "approved" | "rejected" | "invalidated_by_supersession";

/**
 * Payer confirmation status for original bill payer facts and proposed revision payer facts.
 */
export type ExpenseBillPayerConfirmationStatus = "pending_confirmation" | "confirmed" | "rejected";

/**
 * Bounded participant rejection reason code.
 */
export type ExpenseBillParticipantRejectionReasonCode = "wrong_amount" | "wrong_items" | "wrong_split" | "duplicate" | "not_mine" | "other";

/**
 * Expense bill item split method.
 */
export type ExpenseBillItemSplitMethod = "equal" | "exact_amount" | "percentage" | "ratio" | "share_weight";

/**
 * Expense bill adjustment type.
 */
export type ExpenseBillAdjustmentType = "tax" | "service_charge" | "discount" | "manual_adjustment" | "credit";

/**
 * Expense bill adjustment direction.
 */
export type ExpenseBillAdjustmentDirection = "charge" | "credit";

/**
 * Supported adjustment allocation methods for the first personal bill endpoint slice.
 */
export type PersonalBillAdjustmentAllocationMethod = "equal" | "proportional_by_item_subtotal";

/**
 * Supported non-manual adjustment allocation methods for the first group bill endpoint slice.
 */
export type GroupBillAdjustmentAllocationMethod = "equal" | "proportional_by_item_subtotal";

/**
 * Settlement request status returned by settlement request surfaces.
 */
export type SettlementRequestStatus = "requested" | "partially_paid" | "marked_paid" | "confirmed" | "disputed" | "cancelled";

/**
 * Settlement request-line status returned by settlement request surfaces.
 */
export type SettlementRequestLineStatus = "open" | "partially_cleared" | "cleared" | "waived" | "disputed" | "cancelled";

/**
 * Direction of a settlement balance projection from the authenticated actor's perspective.
 */
export type SettlementBalanceDirection = "incoming" | "outgoing";

/**
 * Supported settlement basket selection mode for the first preview and create slices.
 */
export type SettlementBasketSelectionMode = "pay_all_outstanding_for_counterparty";

/**
 * Settlement payment status returned by settlement payment surfaces. Day 1 payment claim creates marked_paid payments, receiver confirmation moves them to confirmed, receiver dispute moves eligible marked_paid claims to disputed, and debtor cancellation moves eligible own marked_paid claims to cancelled.
 */
export type SettlementPaymentStatus = "marked_paid" | "confirmed" | "disputed" | "cancelled";

/**
 * Direction of a proposed settlement residual relative to the exact selected outstanding total.
 */
export type SettlementResidualDirection = "underpayment" | "overpayment";

/**
 * Supported residual policy values for explicit payment-claim-time residual proposals.
 */
export type SettlementResidualPolicy = "remaining_balance" | "carried_forward" | "waived" | "credit_forward" | "waived_by_payer" | "applied_to_other_line";

/**
 * Settlement residual status returned by payment response summaries. Payment claims create pending residuals, receiver residual confirmation moves supported pending residuals to policy-derived confirmed, carried_forward, waived, or credited statuses, and dispute/cancellation neutralizes pending residuals to disputed or cancelled.
 */
export type SettlementResidualStatus = "pending_receiver_confirmation" | "confirmed" | "carried_forward" | "waived" | "credited" | "disputed" | "cancelled";

/**
 * Payment details visibility policy value. The default app behavior is settlement_counterparties_only.
 */
export type PaymentDetailsVisibility = "private" | "settlement_counterparties_only" | "group_members_when_shared";

/**
 * Safe self payment-details response for the authenticated actor. It excludes auth account IDs, session IDs, credential state, audit metadata, counterparty data, storage object keys, storage paths, provider URLs, vault internals, and submitted filenames.
 */
