/**
 * Safe active session metadata for the authenticated account. The list is capped by the API.
 */
export interface SessionListResponse {
  sessions: SessionSummary[];
}

/**
 * Bounded session metadata that excludes token material, hashes, network data, user-agent data, and revocation details.
 */
